ать"},{"en":"cook","ru":"готовить еду"}],"skills":["grammar","vocabulary","reading"],"estimated_minutes":8,"prerequisites":["dc2928a2-aa8b-534b-9f15-ea738abddb5c"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"dd404c58-0979-5e36-b3fd-a3245bad9d87","unit_id":"904766d2-f62a-537b-ad31-e683a1d1a63e","title":"Мои вещи и твои вещи","position":5,"description":"Различаем my/your/his/her и описываем принадлежность знакомых предметов.","level":"A1","objectives":["Использовать притяжательные слова перед существительным","Говорить о наличии вещи с have got"],"notes":["My, your, his, her стоят перед названием предмета: my bag.","I have got a bike и I have a bike могут описывать наличие велосипеда."],"lexicon":[{"en":"mine","ru":"мой, моя, моё (без существительного)"},{"en":"bag","ru":"сумка"},{"en":"bike","ru":"велосипед"},{"en":"whose","ru":"чей"}],"skills":["vocabulary","grammar","reading"],"estimated_minutes":8,"prerequisites":["e3ef702f-5df5-59a9-8dae-22f32b1585a9"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"03b05433-d346-56b8-a574-8f8ca0a921c8","unit_id":"2095a92a-65fa-5d17-aad0-4b342f938689","title":"Как прошли выходные","position":1,"description":"Рассказываем о завершённых событиях и задаём вопросы о прошлом.","level":"A2","objectives":["Использовать Past Simple с yesterday и last weekend","Строить вопросы с did"],"notes":["После did в вопросе используется начальная форма: Did you visit?","Go → went и buy → bought — неправильные формы прошедшего времени."],"lexicon":[{"en":"went","ru":"пошёл, поехал"},{"en":"bought","ru":"купил"},{"en":"last weekend","ru":"в прошлые выходные"},{"en":"enjoy","ru":"наслаждаться, получать удовольствие"}],"skills":["grammar","reading","vocabulary"],"estimated_minutes":8,"prerequisites":[],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"45c3f829-c15f-5d13-b370-ff5db550b3d1","unit_id":"2095a92a-65fa-5d17-aad0-4b342f938689","title":"Выбираем поездку","position":2,"description":"Сравниваем варианты транспорта, время и стоимость без потери смысла.","level":"A2","objectives":["Использовать сравнительную степень прилагательных","Понять причины выбора транспорта"],"notes":["Fast → faster, cheap → cheaper; сравнение вводится than.","Comfortable → more comfortable, не comfortabler."],"lexicon":[{"en":"cheaper","ru":"дешевле"},{"en":"faster","ru":"быстрее"},{"en":"comfortable","ru":"удобный"},{"en":"journey","ru":"поездка"}],"skills":["vocabulary","grammar","reading","listening"],"estimated_minutes":8,"prerequisites":["03b05433-d346-56b8-a574-8f8ca0a921c8"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"2c560bcd-3d5f-5972-b053-7d7af1cd7253","unit_id":"2095a92a-65fa-5d17-aad0-4b342f938689","title":"Планы и договорённости","position":3,"description":"Обсуждаем намерения, простые планы и время встречи.","level":"A2","objectives":["Говорить о намерении с be going to","Подтвердить время и место встречи"],"notes":["Be going to выражает план: I am going to visit …","Let’s … предлагает совместное действие: Let’s meet at six."],"lexicon":[{"en":"plan","ru":"план"},{"en":"meet","ru":"встретиться"},{"en":"next week","ru":"на следующей неделе"},{"en":"free","ru":"свободный (о времени)"}],"skills":["grammar","reading","vocabulary"],"estimated_minutes":8,"prerequisites":["45c3f829-c15f-5d13-b370-ff5db550b3d1"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"e9f8202e-a60b-5e65-a242-1d02190f8f83","unit_id":"2095a92a-65fa-5d17-aad0-4b342f938689","title":"Покупки и количество","position":4,"description":"Спрашиваем о количестве, читаем список покупок и используем much/many.","level":"A2","objectives":["Различать исчисляемые и неисчисляемые существительные","Задавать вопросы How much / How many"],"notes":["Many употребляется с исчисляемыми предметами: many apples.","Much употребляется с неисчисляемым: much milk. Для порций можно назвать bottles или cups."],"lexicon":[{"en":"bottle","ru":"бутылка"},{"en":"receipt","ru":"чек"},{"en":"enough","ru":"достаточно"},{"en":"a few","ru":"несколько (с исчисляемыми)"}],"skills":["vocabulary","grammar","reading"],"estimated_minutes":8,"prerequisites":["2c560bcd-3d5f-5972-b053-7d7af1cd7253"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"09e339df-4a4e-5484-9797-0e4640e6d1aa","unit_id":"2095a92a-65fa-5d17-aad0-4b342f938689","title":"Самочувствие и простые советы","position":5,"description":"Описываем обычные симптомы и понимаем вежливые бытовые советы.","level":"A2","objectives":["Использовать have a headache и feel tired","Давать простой совет с should"],"notes":["I have a headache — у меня болит голова.","Should + начальная форма выражает совет; это языковая практика, а не медицинская консультация."],"lexicon":[{"en":"headache","ru":"головная боль"},{"en":"tired","ru":"уставший"},{"en":"appointment","ru":"запись на приём"},{"en":"rest","ru":"отдыхать"}],"skills":["vocabulary","grammar","reading"],"estimated_minutes":8,"prerequisites":["e9f8202e-a60b-5e65-a242-1d02190f8f83"],"quality":{"status":"checked","method":"author-review + schema/grader/editorial-reference checks","cefr":"provisional","license":"original"},"xp_reward":30},{"id":"56b186bb-4b11-539e-b5b2-f46b7d853676","unit_id":"56873ce9-d184-5617-a3d0-5e04e49fbb0e","title":"Опыт и конкретное прошлое","position":1,"description":"Различаем жизненный опыт и событие, привязанное к завершённому времени.","level":"